import React, { useState, useEffect } from "react";

export default function WithdrawForm({ onCancel }) {
  const [method, setMethod] = useState("bKash");
  const [receiverNumber, setReceiverNumber] = useState("");
  const [amount, setAmount] = useState("");
  const [balance, setBalance] = useState(null);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  // ইউজারের ব্যালেন্স ফেচ করা হচ্ছে
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      setMessage("❌ You must be logged in.");
      return;
    }
    fetch("http://localhost:8080/api/user/balance", {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch balance");
        return res.json();
      })
      .then((data) => {
        setBalance(data.balance);
      })
      .catch((err) => {
        console.error(err);
        setMessage("❌ Could not load balance.");
      });
  }, []);

  // amount চেক করার সময় ব্যালেন্সের সাথে তুলনা
  const handleAmountChange = (e) => {
    const val = e.target.value;
    if (balance !== null && parseFloat(val) > balance) {
      setMessage(`❌ Insufficient balance. Your balance is ${balance}`);
    } else {
      setMessage("");
    }
    setAmount(val);
  };

  const handleWithdraw = async (e) => {
    e.preventDefault();

    setLoading(true);
    setMessage("");

    const token = localStorage.getItem("token");
    if (!token) {
      setMessage("❌ You must be logged in to make a withdraw request.");
      setLoading(false);
      return;
    }

    if (balance !== null && parseFloat(amount) > balance) {
      setMessage(`❌ Insufficient balance. Your balance is ${balance}`);
      setLoading(false);
      return;
    }

    const payload = {
      method,
      receiverNumber,
      amount: parseFloat(amount),
    };

    try {
      console.log("🔄 Sending request with payload:", payload);
      console.log("🪪 Token:", token);

      const res = await fetch("http://localhost:8080/api/withdraw/request", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        setMessage("✅ Withdraw request sent successfully!");
        setReceiverNumber("");
        setAmount("");
        // উইথড্রয়াল হলে ব্যালেন্স আপডেট করতে চাইলে আবার ফেচ করো:
        const updatedBalanceRes = await fetch("http://localhost:8080/api/user/balance", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (updatedBalanceRes.ok) {
          const updatedData = await updatedBalanceRes.json();
          setBalance(updatedData.balance);
        }
      } else {
        const statusCode = res.status;
        let errorMessage = `Status ${statusCode}`;

        try {
          const errorData = await res.json();
          errorMessage += ` - ${errorData.message || JSON.stringify(errorData)}`;
        } catch {
          try {
            errorMessage += ` - ${await res.text()}`;
          } catch {
            // fallback
          }
        }

        console.error("❌ Server responded with error:", errorMessage);
        setMessage("❌ Failed to send withdraw request: " + errorMessage);
      }
    } catch (err) {
      console.error("❌ Network error:", err);
      setMessage("❌ Network error: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <form onSubmit={handleWithdraw} style={styles.form}>
        <h2 style={styles.title}>Withdraw Request</h2>

        <p>Current Balance: {balance !== null ? balance.toFixed(2) : "Loading..."}</p>

        <label style={styles.label}>
          Method:
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            style={styles.select}
          >
            <option value="bKash">bKash</option>
            <option value="Nagad">Nagad</option>
            <option value="Rocket">Rocket</option>
          </select>
        </label>

        <label style={styles.label}>
          Receiver Number:
          <input
            type="text"
            value={receiverNumber}
            onChange={(e) => setReceiverNumber(e.target.value)}
            required
            placeholder="e.g. 017XXXXXXXX"
            style={styles.input}
          />
        </label>

        <label style={styles.label}>
          Amount:
          <input
            type="number"
            step="0.01"
            value={amount}
            onChange={handleAmountChange}
            required
            placeholder="0.00"
            style={styles.input}
          />
        </label>

        <div style={styles.buttonGroup}>
          <button type="submit" style={styles.submitBtn} disabled={loading}>
            {loading ? "Sending..." : "Send Withdraw Request"}
          </button>
          <button
            type="button"
            style={styles.backBtn}
            onClick={onCancel}
            disabled={loading}
          >
            Back
          </button>
        </div>

        {message && (
          <p
            style={
              message.startsWith("✅") ? styles.successMsg : styles.errorMsg
            }
          >
            {message}
          </p>
        )}
      </form>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "80vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: "#f9fafb",
    padding: "20px",
  },
  form: {
    backgroundColor: "#fff",
    padding: "30px 40px",
    borderRadius: "12px",
    boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
    width: "100%",
    maxWidth: "450px",
    boxSizing: "border-box",
  },
  title: {
    marginBottom: "25px",
    color: "#333",
    textAlign: "center",
    fontWeight: "700",
    fontSize: "24px",
  },
  label: {
    display: "block",
    marginBottom: "15px",
    fontWeight: "600",
    color: "#555",
    fontSize: "15px",
  },
  input: {
    width: "100%",
    padding: "10px 14px",
    marginTop: "6px",
    fontSize: "16px",
    borderRadius: "6px",
    border: "1.8px solid #ccc",
    outline: "none",
    transition: "border-color 0.3s ease",
  },
  select: {
    width: "100%",
    padding: "10px 14px",
    marginTop: "6px",
    fontSize: "16px",
    borderRadius: "6px",
    border: "1.8px solid #ccc",
    outline: "none",
    cursor: "pointer",
  },
  buttonGroup: {
    marginTop: "30px",
    display: "flex",
    justifyContent: "space-between",
    gap: "15px",
  },
  submitBtn: {
    flex: 1,
    padding: "12px 0",
    fontSize: "16px",
    fontWeight: "700",
    color: "#fff",
    backgroundColor: "#007bff",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "background-color 0.3s ease",
  },
  backBtn: {
    flex: 1,
    padding: "12px 0",
    fontSize: "16px",
    fontWeight: "700",
    color: "#fff",
    backgroundColor: "#6c757d",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "background-color 0.3s ease",
  },
  successMsg: {
    marginTop: "20px",
    color: "#28a745",
    fontWeight: "600",
    textAlign: "center",
  },
  errorMsg: {
    marginTop: "20px",
    color: "#dc3545",
    fontWeight: "600",
    textAlign: "center",
  },
};
